import React from 'react';
import { motion } from 'framer-motion';
import clsx from 'clsx';
import './AcidTrustedUsers.css';

export interface TrustedUser {
    id: string;
    logo: React.ReactNode;
    name: string;
}

export interface AcidTrustedUsersProps {
    users: TrustedUser[];
    title?: string;
    className?: string;
}

export const AcidTrustedUsers = ({
    users,
    title = "TRUSTED_NODES",
    className
}: AcidTrustedUsersProps) => {
    return (
        <div className={clsx('ac-trusted-container', className)}>
            <div className="ac-trusted-header">
                <div className="ac-trusted-line" />
                <span className="ac-trusted-title">{title}</span>
                <div className="ac-trusted-line" />
            </div>
            <div className="ac-trusted-grid">
                {users.map((user) => (
                    <motion.div
                        key={user.id}
                        whileHover={{ scale: 1.05, filter: 'grayscale(0%)' }}
                        className="ac-trusted-item"
                    >
                        <div className="ac-trusted-logo">
                            {user.logo}
                        </div>
                        <span className="ac-trusted-name">{user.name}</span>
                    </motion.div>
                ))}
            </div>
        </div>
    );
};

.ac-trusted-container {
    width: 100%;
    padding: 3rem 0;
}

.ac-trusted-header {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 3rem;
}

.ac-trusted-line {
    flex: 1;
    height: 1px;
    background: var(--ac-border-muted);
}

.ac-trusted-title {
    font-size: 0.65rem;
    font-family: var(--font-mono);
    color: var(--ac-text-muted);
    letter-spacing: 0.2em;
    white-space: nowrap;
}

.ac-trusted-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 2rem;
    align-items: center;
}

.ac-trusted-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    filter: grayscale(100%);
    opacity: 0.6;
    transition: all 0.3s;
    cursor: default;
}

.ac-trusted-item:hover {
    opacity: 1;
}

.ac-trusted-logo {
    font-size: 2rem;
    color: var(--ac-text-primary);
}

.ac-trusted-name {
    font-size: 0.6rem;
    font-family: var(--font-mono);
    color: var(--ac-text-muted);
    text-transform: uppercase;
}
